/**
 * Shared test builders. Every test uses these instead of hand-rolling entities,
 * so a change in `src/domain/types.ts` breaks one file, not forty.
 *
 * Do NOT edit this file from a feature branch without a good reason: all the
 * test suites depend on it.
 */

import type {
  AccessLevel,
  Attachment,
  Control,
  ControlInput,
  ControlStatus,
  Evidence,
  EvidenceFields,
  Framework,
  FrameworkImport,
  Principal,
  ReadFlags,
  Settings,
  Sufficiency,
  SufficiencyElement,
  TextPage,
  ValidationItem
} from '../../src/domain/types.ts';
import { DEFAULT_SETTINGS } from '../../src/domain/types.ts';
import type { PackManifest, PackSignature } from '../../src/domain/verification.ts';
import { sha256Json } from '../../src/support/hash.ts';

export const TEST_NOW = '2026-11-11T12:00:00.000Z';
export const TEST_TODAY = '2026-11-11';

let counter = 0;
/** Unique suffix so two builders never collide inside one test file. */
export function nextId(prefix: string): string {
  counter += 1;
  return `${prefix}-${counter}`;
}

export function makeFramework(overrides: Partial<Framework> = {}): Framework {
  return {
    id: 'demo-msp',
    name: 'Demonstration framework',
    version: '1.0',
    importedAt: TEST_NOW,
    confidentiality: 'INTERNAL',
    ...overrides
  };
}

export function makeControl(overrides: Partial<Control> = {}): Control {
  return {
    id: 'CONT-01',
    frameworkId: 'demo-msp',
    domain: 'Governance',
    title: 'Information security policy reviewed annually',
    requirement: 'The information security policy is reviewed and approved at least once a year.',
    expectedEvidence: ['Policy title', 'Review date', 'Approver name', 'Version'],
    periodicity: 'P1Y',
    owner: 'quality.lead',
    mandatory: true,
    ...overrides
  };
}

export function makeControlInput(overrides: Partial<ControlInput> = {}): ControlInput {
  const control = makeControl(overrides);
  return {
    id: control.id,
    domain: control.domain,
    title: control.title,
    requirement: control.requirement,
    expectedEvidence: control.expectedEvidence,
    periodicity: control.periodicity,
    owner: control.owner,
    mandatory: control.mandatory,
    ...overrides
  };
}

export function makeFrameworkImport(controls: ControlInput[], overrides: Partial<FrameworkImport['framework']> = {}): FrameworkImport {
  return {
    framework: { id: 'demo-msp', name: 'Demonstration framework', version: '1.0', ...overrides },
    controls
  };
}

export function makeFields(overrides: Partial<EvidenceFields> = {}): EvidenceFields {
  return {
    type: 'POLICY',
    title: 'Information security policy',
    documentDate: '2026-08-01',
    period: { start: null, end: null },
    version: '3.1',
    author: 'A. Dupont',
    approver: 'C. Bernard',
    approvalDate: '2026-08-05',
    client: null,
    summary: 'Annual review of the information security policy, approved by the steering committee.',
    personalData: false,
    ...overrides
  };
}

export function makeFlags(overrides: Partial<ReadFlags> = {}): ReadFlags {
  return { unreadable: false, missingDate: false, missingAuthor: false, dateToConfirm: false, ...overrides };
}

export function makePages(text: string, pages = 1): TextPage[] {
  return Array.from({ length: pages }, (_, index) => ({ page: index + 1, text }));
}

export function makeEvidence(overrides: Partial<Evidence> = {}): Evidence {
  const text =
    overrides.textPages?.[0]?.text ??
    'Information security policy version 3.1, reviewed on 1 August 2026 and approved by C. Bernard.';
  return {
    id: nextId('ev'),
    sha256: 'a'.repeat(64),
    revision: 1,
    fields: makeFields(),
    flags: makeFlags(),
    accessLevel: 'INTERNAL' as AccessLevel,
    locations: [{ kind: 'MANUAL', uri: 'manual://policy.pdf', collectedAt: TEST_NOW }],
    textPages: makePages(text),
    sizeBytes: 2048,
    contentType: 'application/pdf',
    ingestedAt: TEST_NOW,
    reader: 'mock',
    ...overrides
  };
}

export function makeAttachment(overrides: Partial<Attachment> = {}): Attachment {
  return {
    id: nextId('at'),
    evidenceId: 'ev-1',
    controlId: 'CONT-01',
    frameworkId: 'demo-msp',
    supports: true,
    confidence: 0.93,
    quote: 'reviewed on 1 August 2026 and approved by C. Bernard',
    quoteLocation: { page: 1 },
    reason: 'The document states the review date and the approver required by the control.',
    status: 'APPLIED',
    citationVerified: true,
    autoApplied: true,
    model: 'mock-reasoner',
    createdAt: TEST_NOW,
    ...overrides
  };
}

export function makeElements(presentFlags: boolean[], expected: string[] = ['Policy title', 'Review date', 'Approver name', 'Version']): SufficiencyElement[] {
  return expected.map((name, index) => ({
    expected: name,
    present: presentFlags[index % presentFlags.length] ?? false,
    quote: (presentFlags[index % presentFlags.length] ?? false) ? `"${name}" found in the document` : null
  }));
}

export function makeSufficiency(overrides: Partial<Sufficiency> = {}): Sufficiency {
  const elements = overrides.elements ?? makeElements([true, true, true, true]);
  return {
    id: nextId('sf'),
    attachmentId: 'at-1',
    evidenceId: 'ev-1',
    controlId: 'CONT-01',
    elements,
    class: 'COMPLETE',
    missing: [],
    computedAt: TEST_NOW,
    ...overrides
  };
}

export function makeStatus(overrides: Partial<ControlStatus> = {}): ControlStatus {
  return {
    controlId: 'CONT-01',
    frameworkId: 'demo-msp',
    state: 'COVERED',
    freshness: 'FRESH',
    sufficiencyClass: 'COMPLETE',
    bestEvidenceId: 'ev-1',
    expiresAt: '2027-08-01T00:00:00.000Z',
    pendingProposals: 0,
    notes: [],
    computedAt: TEST_NOW,
    ...overrides
  };
}

export function makeValidation(overrides: Partial<ValidationItem> = {}): ValidationItem {
  return {
    id: nextId('va'),
    kind: 'ATTACHMENT',
    attachmentId: 'at-1',
    evidenceId: 'ev-1',
    controlId: 'CONT-01',
    reason: 'confidence below threshold',
    createdAt: TEST_NOW,
    status: 'PENDING',
    ...overrides
  };
}

export function makePrincipal(overrides: Partial<Principal> = {}): Principal {
  return {
    id: 'u-quality',
    name: 'Quality lead',
    email: 'quality@msp.demo',
    role: 'QUALITY_LEAD',
    clearance: 'RESTRICTED',
    ownedControls: [],
    ...overrides
  };
}

/** A minimal canonical manifest, hash consistent with its content. */
export function makeManifest(overrides: Partial<PackManifest> = {}): PackManifest {
  const base: Omit<PackManifest, 'rootHash'> = {
    packId: 'pk-fixture',
    frameworkId: 'demo-msp',
    frameworkVersion: '1.0',
    frozenAt: TEST_NOW,
    controlCount: 0,
    evidenceCount: 0,
    knownGapCount: 0,
    controls: [],
    ...overrides
  };
  return { ...base, rootHash: overrides.rootHash ?? sha256Json(base) };
}

/** A signature of `makeManifest()`, shaped like a local Ed25519 one. */
export function makeSignature(overrides: Partial<PackSignature> = {}): PackSignature {
  return {
    algorithm: 'ED25519-LOCAL',
    keyId: 'test-key',
    signedAt: TEST_NOW,
    signature: 'c2lnbmF0dXJl',
    rootHash: makeManifest().rootHash,
    ...overrides
  };
}

export function makeSettings(overrides: Partial<Settings> = {}): Settings {
  return { ...DEFAULT_SETTINGS, ...overrides };
}
